const raw=$('Get OpusClip Clips').first().json;
const clips=Array.isArray(raw)?raw:(raw.data??raw.items??raw.clips??[]);
const prepared=$('Prepare Opus Action').first().json;
if(prepared.sourceKind!=='final')throw new Error('Only a registered short-clipping project may be imported as Content Clips.');
const projectId=prepared.projectId,parentId=prepared.recordId;
const token=/^[A-Za-z0-9_-]+$/;
for(const c of clips){
 const id=String(c.id??''),pid=String(c.projectId??''),curation=String(c.curationId??'');
 const plain=token.test(id);
 const composite=token.test(pid)&&token.test(curation)&&id===pid+'.'+curation;
 if(!plain&&!composite)throw new Error('Unexpected provider clip ID format; reconcile before importing.');
 if(pid!==String(projectId))throw new Error('Provider clip project does not match the registered short project.');
}

const airtable=$('Get Airtable Content').first().json.fields??{};
const requested=Math.max(1,Math.min(50,Math.round(Number(airtable['Requested Clip Count']??5))));
const minimum=Number(airtable['Minimum Clip Score']??85);
if(!Number.isFinite(minimum))throw new Error('Minimum clip score must be numeric.');
if((airtable['Content Clips']??[]).length)throw new Error('This content already has imported clips. Review the existing clips; do not re-import. Reconcile any partial previous import first.');const existingIds=new Set();
const ranked=clips.filter(c=>String(c.projectId??'')===String(projectId)&&Number(c.viralityScore??c.score??0)>=minimum).sort((a,b)=>Number(b.viralityScore??b.score??0)-Number(a.viralityScore??a.score??0));
const seen=new Set();const matches=ranked.filter(c=>{const k=String(c.id??'');if(!k||seen.has(k))return false;seen.add(k);return true;}).slice(0,requested);
if(!matches.length)throw new Error('No exportable clips meet the minimum score '+minimum+' yet. Keep the existing project; do not resubmit.');
const records=matches.filter(c=>!existingIds.has(String(c.id))).map(c=>({fields:{'Clip Name':String(c.title??c.id),'OpusClip Clip ID':String(c.id),'Frame.io Clip URL':String(c.uriForExport??c.uriForPreview??''),'Virality Score':Number(c.viralityScore??c.score??0),'Hook':String(c.text??c.promptName??''),'Clip Transcript':String(c.text??''),'Caption':[c.description,c.hashtags].filter(Boolean).join('\n\n'),'Clip Status':'Needs Review','Parent Content':[parentId]}}));
const markReadyBody=JSON.stringify({fields:{'OpusClip Status':'Clips Ready','OpusClip Short Job State':'Clips Ready','Production Stage':'Ready for Clips','Last Automation Message':matches.length+' qualifying OpusClip clips available for review; '+records.length+' newly imported.','Automation Error':''}});
if(!records.length)return [{json:{records:[],parentId,count:matches.length,hasNewClips:false,markReadyBody}}];
const out=[];for(let i=0;i<records.length;i+=10){const batch=records.slice(i,i+10);out.push({json:{records:batch,parentId,count:matches.length,hasNewClips:true,createClipsBody:JSON.stringify({records:batch,typecast:false}),markReadyBody}});}return out;
